<template>
  <div
    class="row q-mb-sm q-pa-sm warning-holder text-weight-bold text-red font-size-medium full-width"
  >
    <span style="width: 100%">
      {{ $t('custom_column_change_warning') }}
    </span>
  </div>

  <div
    class="row q-mb-sm q-pa-sm error-holder full-width"
    v-if="no_table_warning"
  >
    <span style="width: 100%">
      {{ $t('no_table_exists') }}
    </span>
  </div>

  <div class="row full-width q-mb-sm q-mt-md">
    <q-input
      style="width: 300px"
      dense
      outlined
      debounce="300"
      color="primary"
      v-model="filter"
    >
      <template v-slot:append>
        <q-icon name="search" />
      </template>
    </q-input>
    <q-space />
    <f-btn
      class="q-mr-sm"
      :label="$t('create_new_table')"
      @click="displayCreateTableDialog = true"
    />
    <f-btn
      :label="$t('add_new_table_column')"
      @click="addColumnDialog = true"
    />
  </div>

  <DocBitsTable
    :rows="filteredRows"
    :columns="columns"
    row-key="id"
    table-id="custom_column_table"
    :loading="loading"
    dense
    :features="{
      sorting: false,
      filtering: false,
      selection: false,
      bulkActions: false,
      rowActions: true,
      resizable: false,
      pagination: false,
      columnReorder: true,
      stickyLastColumn: true,
    }"
    :row-actions="customColRowActions"
    :column-order="columnOrder"
    :table-height="table_height + 'vh'"
    no-data-label="no_record_found"
    flat-style
    @row-action="handleRowAction"
    @column-reorder="handleColumnReorder"
  >
    <template #body-cell-column_name="{ row }">
      <q-input borderless dense style="background: transparent" v-model="row.column_name" :readonly="row.id !== ''" />
    </template>
    <template #body-cell-title="{ row }">
      {{ row.title }}
      <q-popup-edit v-model="row.title" title="Update title" v-slot="scope">
        <q-input v-model="scope.value" dense autofocus @keyup.enter="scope.set" @keydown.enter="updateColumnTitle(row.id, scope.value)" />
      </q-popup-edit>
    </template>
    <template #body-cell-column_type="{ row }">
      <q-input borderless dense v-model="row.column_type" :readonly="row.id !== ''" />
    </template>
    <template #body-cell-table_name="{ row }">
      <q-input borderless dense v-model="row.table_name" :readonly="row.id !== ''" />
    </template>
    <template #body-cell-is_required="{ row }">
      <q-checkbox v-model="row.is_required" @update:model-value="(val: boolean) => updateBooleanProperties(val, rows.indexOf(row), row.id, 'is_required')" />
    </template>
    <template #body-cell-is_readonly="{ row }">
      <q-checkbox v-model="row.is_readonly" @update:model-value="(val: boolean) => updateBooleanProperties(val, rows.indexOf(row), row.id, 'is_readonly')" />
    </template>
    <template #body-cell-hidden="{ row }">
      <q-checkbox v-model="row.is_hidden" @update:model-value="(val: boolean) => updateBooleanProperties(val, rows.indexOf(row), row.id, 'is_hidden')" />
    </template>
    <template #body-cell-use_ai="{ row }">
      <q-checkbox :model-value="getColumnUseAi(row)" @update:model-value="(val: boolean) => setColumnUseAi(val, row)" />
    </template>
  </DocBitsTable>

  <!-- Add New Column -->
  <q-dialog
    v-model="addColumnDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="addColumnDialog = false"
  >
    <CreateCustomColumn
      :is_table_training_doc="false"
      :is_table_extraction_view="false"
      table_name=""
      :tables_list="tables_list"
      :tables="[]"
      :columns_list="columns_list"
      :addColumnDialog="addColumnDialog"
      parent_view="columns_list"
      :table_list_loading="table_list_loading"
    />
  </q-dialog>
  <!-- END Add New Column -->

  <!-- Add New Table -->
  <q-dialog
    v-model="displayCreateTableDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="displayCreateTableDialog = false"
  >
    <CreateTable :doc_type="doc_type" />
  </q-dialog>
  <!-- END Add New Table -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { LocalStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import CreateTable from './Create-Table.vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { documentTypeApiService } from 'src/services';
import dragDropColumn from 'src/mixins/dragDropColumn';
import CreateCustomColumn from './Create-Custom-Column.vue';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem } from 'src/components/Table/types/table/unified-table';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  mixins: [helperMixin],
  components: {
    CreateCustomColumn,
    CreateTable,
    DocBitsTable,
  },
  props: {
    table_height: {
      type: String,
      default: '55',
    },
  },
  data() {
    return {
      selectedTitle: ref(''),
    };
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const needle = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        for (const [_key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(needle)) return true;
        }
        return false;
      });
    },
  },
  mounted: function () {
    this.prepareColumns();
    this.getTableName();
    this.fetchColumns();

    document.addEventListener('new_table_created', this.newTableCreated);
    document.addEventListener('custom_column_create', this.customColumnCreated);
  },
  unmounted: function () {
    document.removeEventListener('new_table_created', this.newTableCreated);
    document.removeEventListener(
      'custom_column_create',
      this.customColumnCreated,
    );
  },
  methods: {
    prepareColumns() {
      this.columns = [
        { name: 'column_name', label: 'column_name', field: 'column_name', align: 'left' },
        { name: 'title', label: 'title', field: 'title', align: 'left' },
        { name: 'column_type', label: 'column_type', field: 'column_type', align: 'left' },
        { name: 'table_name', label: 'table_name', field: 'table_name', align: 'left' },
        { name: 'is_required', label: 'is_required', field: 'is_required', align: 'left' },
        { name: 'is_readonly', label: 'read_only', field: 'is_readonly', align: 'left' },
        { name: 'hidden', label: 'hidden', field: 'hidden', align: 'left' },
        { name: 'use_ai', label: 'use_ai', field: 'use_ai', align: 'left' },
      ];

      const saved_columns = LocalStorage.getItem('CUSTOM_TABLE_SETTING_COLUMNS') as string;
      if (saved_columns) {
        try {
          const parsed = JSON.parse(saved_columns);
          this.columnOrder = parsed.map((c: any) => c.name).filter((n: string) => n !== 'action');
        } catch {
          // ignore
        }
      }
    },

    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      const orderedColumns = newOrder
        .map((name: string) => this.columns.find((c: any) => c.name === name))
        .filter(Boolean);
      LocalStorage.set('CUSTOM_TABLE_SETTING_COLUMNS', JSON.stringify(orderedColumns));
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.handleDelete(row);
      }
    },

    getTableName() {
      this.doc_type = String(this.$route.params.type);
      return String(this.doc_type);
    },

    async fetchColumns() {
      let response: any;
      try {
        this.loading = true;
        const response = await documentTypeApiService.getTableColumns(
          this.getTableName(),
        );

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.success === false
        ) {
          throw response;
        }

        let data = [];

        for (let [tbl_name, tbl] of Object.entries(response.data)) {
          const table = tbl as dynamicObj;
          for (let [index, col] of Object.entries(table)) {
            const row = col as dynamicObj;
            let newRow: dynamicObj = { ...row };
            newRow['table_name'] = tbl_name;
            data.push(newRow);
          }
        }
        this.prepareRows(data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
        this.loading = false;
      }
    },

    prepareRows(data: any) {
      this.rows = [] as any;
      this.columns_list = {} as { [k: string]: any };
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
        if (row && row.hasOwnProperty('column_name')) {
          this.addToColumnList(row.column_name);
        }
      }
      this.prepareTableList();
    },

    addNewRow(column: any) {
      let newRow: dynamicObj = { ...column };
      newRow['name'] = column.column_name;
      newRow['label'] = this.getLabelToDisplay(column);
      newRow['processing_visibility'] = false;
      newRow['processing_delete'] = false;
      newRow['is_hidden'] = !newRow.is_hidden ? false : true;
      this.rows.push(newRow);
      return newRow;
    },

    getLabelToDisplay(column: any) {
      let label = column.title as string;
      if (
        this.$t(column.translation_key) !==
        'pages.line_items_columns.' + column.translation_key
      ) {
        label = this.$t(column.translation_key);
      }
      return label;
    },

    getRow(id: string) {
      const selectedIndex = this.rows.findIndex((item: any) => item.id == id);
      return selectedIndex as number;
    },

    async updateColumnTitle(rowId: string, title: string) {
      if (this.selectedTitle === title) {
        this.selectedTitle = '';
        return;
      }

      this.selectedTitle = '';

      try {
        this.loading = true;
        let formData = new FormData();
        formData.append('title', title);
        await this.updateRow(rowId, formData);
        return true;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async handleDelete(row: any) {
      const index = this.getRow(row.id);
      try {
        this.rows[index].processing_delete = true;
        this.loading = true;
        let formData = new FormData();
        formData.append(
          'is_deleted',
          row.is_deleted === true ? 'false' : 'true',
        );
        await this.updateRow(row.id, formData);
        this.rows.splice(index, 1);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.rows[index].processing_delete = false;
        this.loading = false;
      }
    },

    async updateBooleanProperties(
      val: boolean,
      rowIndex: any,
      rowId: string,
      columnName: string,
    ) {
      try {
        if (!columnName) {
          return;
        }
        this.loading = true;
        let formData = new FormData();
        formData.append(columnName, val === false ? 'false' : 'true');
        await this.updateRow(rowId, formData);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    // additional_attributes is stored as a JSON string on the column. Parse it
    // defensively — it may be a string, an already-parsed object, or empty.
    parseAdditionalAttributes(raw: any): dynamicObj {
      if (!raw) {
        return {};
      }
      if (typeof raw === 'object') {
        return { ...raw };
      }
      if (typeof raw === 'string') {
        try {
          return JSON.parse(raw) || {};
        } catch {
          return {};
        }
      }
      return {};
    },
    getColumnUseAi(row: any): boolean {
      return this.parseAdditionalAttributes(row.additional_attributes).use_ai === true;
    },
    async setColumnUseAi(val: boolean, row: any) {
      try {
        this.loading = true;
        const attrs = this.parseAdditionalAttributes(row.additional_attributes);
        attrs.use_ai = val === true;
        // Persist as a JSON string (matches how additional_attributes is stored
        // on create) and keep the local row in sync for the checkbox.
        row.additional_attributes = JSON.stringify(attrs);
        const formData = new FormData();
        formData.append('additional_attributes', row.additional_attributes);
        await this.updateRow(row.id, formData);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async updateRow(rowId: string, formData: FormData) {
      let response = await documentTypeApiService.updateTableCustomColumn(
        rowId,
        formData,
      );

      if (!response.success || response.success !== true) {
        throw response.data.message
          ? response.data.message
          : {
              message:
                'Response dont have table_data index/success is set to false',
            };
      }
    },

    addToColumnList(column_name: string) {
      this.columns_list[column_name] = column_name;
    },

    newTableCreated() {
      this.displayCreateTableDialog = false;
      this.prepareTableList();
    },

    async prepareTableList() {
      this.tables_list = [] as any;
      this.tables_list.push(
        Object.assign(
          {},
          {
            value: '',
            label: this.$t('select_table'),
          },
        ),
      );

      let response;
      try {
        this.loading = true;
        this.no_table_warning = false;
        this.table_list_loading = true;
        this.showLoading();
        response = await documentTypeApiService.getTable(this.doc_type);

        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.success === false
        ) {
          throw response;
        }

        if (response.data && response.data.length === 0) {
          this.no_table_warning = true;
          return;
        }

        response.data.forEach((element: any) => {
          this.tables_list.push(
            Object.assign(
              {},
              {
                value: element.table_name,
                label: element.table_name,
              },
            ),
          );
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
        this.loading = false;
        this.table_list_loading = false;
      }
    },

    customColumnCreated(e: any) {
      this.addColumnDialog = false;
      this.fetchColumns();
    },
  },
  setup() {
    const filter = ref('');
    let data: any = [];
    let model: { [k: string]: any } = {};
    const columns = ref(data);
    const customColRowActions: RowActionItem[] = [
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', show: (row: any) => row.id !== '' && row.org_id !== DEFAULT_ORG_UUID },
    ];

    return {
      columns,
      columnOrder: ref([] as string[]),
      customColRowActions,
      filter,
      rows: ref(data),
      loading: ref(false),
      addColumnDialog: ref(false),
      columns_list: ref(model),
      tables_list: ref([] as any),
      doc_type: ref(''),
      displayCreateTableDialog: ref(false),
      no_table_warning: ref(false),
      table_list_loading: ref(false),
    };
  },
});
</script>

