<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('create_new_table') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="'full-width '"
              v-model="new_model['table_name']"
              :label="$t('table_name')"
              :hint="message"
              :error-message="new_model['name_error_msg']"
              :error="new_model['name_error']"
            >
            </q-input>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { stringWithoutSpaces } from 'src/utils/general';
import { documentTypeApiService } from 'src/services';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
  },
  components: {},
  data() {
    return {
      message: i18n.t('field_only_characters'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_model: ref(model),
      token: ref(''),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    setNewModel() {
      this.new_model['table_name'] = '';
      this.new_model['name_error'] = false;
      this.new_model['name_error_msg'] = '';
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let response: any;

      const data = {
        table_name: this.new_model['table_name'],
        doc_type_name: this.doc_type,
        is_default: false,
      };
      response = await documentTypeApiService.createTable(data);

      if (
        response.data &&
        response.data.hasOwnProperty('success') &&
        response.data.success === false
      ) {
        throw { message: response.data.message };
      }

      const event = new CustomEvent('new_table_created', {
        detail: { data: response.data },
      });
      document.dispatchEvent(event);
      notify.success('Table Created successfully');
      this.setNewModel();
    },

    validateRow(row: any) {
      let validate = true;
      this.new_model['name_error'] = false;
      this.new_model['name_error_msg'] = '';

      if (!row['table_name'] || row['table_name'].length == 0) {
        this.new_model['name_error_msg'] = 'Table Name is required';
        this.new_model['name_error'] = true;
        return false;
      }

      if (!stringWithoutSpaces(row['table_name'])) {
        this.new_model['name_error_msg'] =
          'Field Name can only contain characters, numbers, hyphen and underscore';
        this.new_model['name_error'] = true;
        return false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
